0CREATE OR REPLACE DICTIONARY IF NOT EXISTS db.d ON CLUSTER c (id UInt64, name String DEFAULT '' EXPRESSION lower(n) HIERARCHICAL INJECTIVE,) PRIMARY KEY id SOURCE(CLICKHOUSE(HOST 'h' PORT 9000 PASSWORD 'p' TABLE 't' DB currentDatabase())) LAYOUT(COMPLEX_KEY_HASHED(SHARDS 4)) LIFETIME(MIN 0 MAX 1000) RANGE(MIN a MAX b) SETTINGS(x = 0) COMMENT 'x';
CREATE VIEW IF NOT EXISTS db.v ON CLUSTER c (a UInt8) DEFINER = u SQL SECURITY DEFINER AS SELECT 1 AS a COMMENT 'x';
CREATE DATABASE IF NOT EXISTS d ON CLUSTER c ENGINE = Replicated('/x', '{shard}', '{replica}') COMMENT 'x';
CREATE OR REPLACE FUNCTION f ON CLUSTER c AS (x, y) -> if(x > y, x, y);
